// Validate and normalize notification request
const body = $input.first().json.body || $input.first().json;

const channel = body.channel || 'telegram';
const validChannels = ['telegram', 'email', 'push', 'webhook'];

if (!validChannels.includes(channel)) {
  throw new Error(`Channel '${channel}' tidak valid. Valid: ${validChannels.join(', ')}`);
}

if (!body.message && !body.subject) {
  throw new Error('Field message atau subject wajib disertakan');
}

return [{
  json: {
    notification_type: body.notification_type || 'general',
    channel: channel,
    recipient: body.recipient || null,
    subject: body.subject || 'AgriSensa Notification',
    message: body.message || body.subject || '',
    payload: body.payload || {},
    triggered_by: body.triggered_by_workflow || 'manual',
    notification_id: `notif_${Date.now()}_${Math.random().toString(36).substr(2,6)}`
  }
}];

