// Merge all notification results
const items = $input.all();
const validatorData = $('✅ Notification Validator').item.json;

const results = items.map(item => ({
  channel: validatorData.channel,
  status: item.json.ok || item.json.success || item.json.message_id ? 'sent' : 'error',
  response: item.json
}));

return [{
  json: {
    notification_id: validatorData.notification_id,
    channel: validatorData.channel,
    notification_type: validatorData.notification_type,
    subject: validatorData.subject,
    message: validatorData.message,
    triggered_by: validatorData.triggered_by,
    results: results,
    overall_status: results.every(r => r.status === 'sent') ? 'sent' : 'partial_failure'
  }
}];
